/** Campaign UI QA through actual Import save, mouse and keyboard input.
 * Fixtures are generated by the complete public-action simulation in stichos-campaign.test.ts.
 * VERSO_QA_FIXTURES=1 node --experimental-strip-types --test --test-name-pattern='whole generation-three' tests/stichos-campaign.test.ts
 * node scripts/browser-stichos-campaign.mjs http://127.0.0.1:WORKSPACE_CDP http://localhost:4174/
 * Add --forge for component selection, actual gathering/costs, equipment, save/mobile and disabled-shop checks.
 * Never attach to host Chrome; every run uses an isolated browser context.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const endpoint = process.argv[2],
  url = process.argv[3] ?? 'http://localhost:4174/';
if (
  !endpoint ||
  !['localhost', '127.0.0.1'].includes(new URL(endpoint).hostname) ||
  new URL(url).hostname !== 'localhost'
)
  throw Error('Use workspace CDP and localhost game origin.');
const forgeMode = process.argv.includes('--forge');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const folder = `verso-stichos-ending-${Date.now()}`,
  hostDir = `/home/sabino/.local/share/agent-workspace-linux/files/${folder}`,
  workspaceDir = `/workspace/agent/${folder}`;
const out = path.join(
  root,
  forgeMode ? '.dream-loop/stichos-forge-browser' : '.dream-loop/stichos-campaign-browser',
);
fs.mkdirSync(hostDir, { recursive: true });
fs.mkdirSync(out, { recursive: true });
for (const name of ['before-final-puzzle', 'before-ending', 'campaign-complete', 'free-life-home'])
  fs.copyFileSync(
    path.join(root, '.dream-loop/campaign-fixtures', `${name}.json`),
    path.join(hostDir, `${name}.json`),
  );
const results = [],
  errors = [],
  screenshots = [];
let browser, page, contextId, chooser, failure;
const delay = (ms) => new Promise((r) => setTimeout(r, ms));
const assert = (ok, text) => {
  if (!ok) throw Error(text);
};
const pass = (name, detail = '') => {
  results.push({ name, detail });
  console.log(`PASS ${name}: ${detail}`);
};
const state = () => read('window.stichos.state');
const distance = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
async function mouse(x, y, button = 'left') {
  await page.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y });
  await page.send('Input.dispatchMouseEvent', {
    type: 'mousePressed',
    x,
    y,
    button,
    clickCount: 1,
  });
  await page.send('Input.dispatchMouseEvent', {
    type: 'mouseReleased',
    x,
    y,
    button,
    clickCount: 1,
  });
  await delay(150);
}
async function connect(address, events = () => {}) {
  const ws = new WebSocket(address);
  await new Promise((resolve, reject) => {
    ws.onopen = resolve;
    ws.onerror = reject;
  });
  let id = 0;
  const pending = new Map();
  ws.onmessage = ({ data }) => {
    const m = JSON.parse(data);
    if (!m.id) return events(m.method, m.params);
    const p = pending.get(m.id);
    if (!p) return;
    clearTimeout(p.timer);
    pending.delete(m.id);
    if (m.error) p.reject(Error(JSON.stringify(m.error)));
    else p.resolve(m.result);
  };
  return {
    send(method, params = {}) {
      return new Promise((resolve, reject) => {
        const n = ++id;
        pending.set(n, {
          resolve,
          reject,
          timer: setTimeout(() => {
            pending.delete(n);
            reject(Error(`Timeout: ${method}`));
          }, 20000),
        });
        ws.send(JSON.stringify({ id: n, method, params }));
      });
    },
    close() {
      ws.close();
    },
  };
}
async function read(expression) {
  const r = await page.send('Runtime.evaluate', {
    expression,
    returnByValue: true,
    awaitPromise: true,
  });
  if (r.exceptionDetails) throw Error(JSON.stringify(r.exceptionDetails));
  return r.result.value;
}
async function waitFor(expression, label, ms = 20000) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    if (await read(expression).catch(() => false)) return;
    await delay(100);
  }
  throw Error(`Timed out: ${label}`);
}
async function click(selector) {
  let rect;
  for (let attempt = 0; attempt < 12; attempt++) {
    rect = await read(
      `(()=>{const e=document.querySelector(${JSON.stringify(selector)});if(!e||e.disabled)return null;const r=e.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,w:r.width,h:r.height,vw:innerWidth,vh:innerHeight}})()`,
    );
    assert(rect, `Missing or disabled control: ${selector}`);
    if (
      rect.w > 0 &&
      rect.h > 0 &&
      rect.y >= 6 &&
      rect.y < rect.vh - 6 &&
      rect.x >= 0 &&
      rect.x < rect.vw
    )
      break;
    await page.send('Input.dispatchMouseEvent', {
      type: 'mouseWheel',
      x: Math.max(8, Math.min(rect.vw - 8, rect.x)),
      y: rect.vh / 2,
      deltaX: 0,
      deltaY: rect.y < 6 ? -rect.vh * 0.65 : rect.vh * 0.65,
    });
    await delay(180);
  }
  assert(
    rect.w > 0 && rect.h > 0 && rect.x >= 0 && rect.x < rect.vw && rect.y >= 0 && rect.y < rect.vh,
    `Control outside viewport: ${selector}`,
  );
  await mouse(rect.x, rect.y);
}
async function key(key, code, vk, ms = 0) {
  await page.send('Input.dispatchKeyEvent', {
    type: 'keyDown',
    key,
    code,
    windowsVirtualKeyCode: vk,
  });
  if (ms) await delay(ms);
  await page.send('Input.dispatchKeyEvent', {
    type: 'keyUp',
    key,
    code,
    windowsVirtualKeyCode: vk,
  });
  await delay(150);
}
async function shot(name) {
  const r = await page.send('Page.captureScreenshot', {
    format: 'png',
    captureBeyondViewport: false,
  });
  fs.writeFileSync(path.join(out, `${name}.png`), Buffer.from(r.data, 'base64'));
}
async function pause() {
  if (await read("window.stichos.state.modal === 'pause'")) return;
  await key('Escape', 'Escape', 27);
  await waitFor("window.stichos.state.modal === 'pause'", 'pause');
}
async function importFile(filename) {
  await pause();
  chooser = undefined;
  await click('#s-load-file');
  const end = Date.now() + 3000;
  while (!chooser && Date.now() < end) await delay(50);
  assert(chooser, 'Restore did not open a file chooser');
  await page.send('DOM.setFileInputFiles', {
    backendNodeId: chooser.backendNodeId,
    files: [`${workspaceDir}/${filename}`],
  });
  await delay(300);
}
async function worldClick(point) {
  const pos = await read(
    `(()=>{const p=window.stichos.worldToScreen(${JSON.stringify(point)}),r=document.querySelector('#s-world').getBoundingClientRect();return{x:r.left+p.x,y:r.top+p.y}})()`,
  );
  await mouse(pos.x, pos.y);
}
async function closeModal() {
  for (let i = 0; i < 4; i++) {
    const s = await state();
    if (!s.modal && !s.dialogue) return;
    await key('Escape', 'Escape', 27);
  }
  assert(!(await state()).modal, 'Modal did not close');
}
async function walk(point, range = 0.6) {
  await closeModal();
  await worldClick(point);
  await waitFor(
    `Math.hypot(window.stichos.state.player.x-(${point.x}),window.stichos.state.player.y-(${point.y}))<${range}`,
    'actual click walking',
    25000,
  );
}
async function interact(target) {
  await closeModal();
  await worldClick({ x: target.x, y: target.y - 0.25 });
  await waitFor(
    `window.stichos.state.dialogue?.npcId===${JSON.stringify(target.id)}`,
    'actual dialogue ' + target.id,
    25000,
  );
}
async function choose(id) {
  await click(`[data-choice=${JSON.stringify(id)}]`);
}
async function life(tab = 'purpose') {
  await closeModal();
  await click('#s-life');
  await waitFor("window.stichos.state.modal==='life'", 'Life panel');
  await click(`[data-life-tab="${tab}"]`);
}
async function lifeButton(label) {
  const selector = await read(
    `(()=>{const b=[...document.querySelectorAll('#s-life-panel button[data-life-action]')].find(b=>b.textContent.startsWith(${JSON.stringify(label)})&&!b.disabled);return b?'[data-life-action="'+b.dataset.lifeAction+'"]':null})()`,
  );
  assert(selector, 'No enabled life action ' + label);
  await click(selector);
}
async function selectOption(selector, index) {
  await click(selector);
  await key('Home', 'Home', 36);
  for (let i = 0; i < index; i++) await key('ArrowDown', 'ArrowDown', 40);
  await key('Enter', 'Enter', 13);
  assert(
    await read(`document.querySelector(${JSON.stringify(selector)}).selectedIndex===${index}`),
    'Native select did not choose ' + selector,
  );
}
async function forgeChoices() {
  await selectOption('#s-forge-kind', 0);
  await selectOption('#s-forge-material', 1);
  await selectOption('#s-forge-core', 1);
  await selectOption('#s-forge-span', 2);
}
async function forgeUi() {
  return read(
    `(()=>{const p=document.querySelector('.s-forge-preview');return {name:p.querySelector('h3').textContent, profile:[...p.querySelectorAll('dd')].map(d=>d.childNodes[0].textContent.trim()), icon:p.querySelector('svg').innerHTML, price:document.querySelector('.s-forge-price').textContent, disabled:document.querySelector('#s-forge-build').disabled}})()`,
  );
}
